svg.script:
(function () {
  var W = 340, H = 300;
  var p1 = document.getElementById('p1'), p2 = document.getElementById('p2'), ball = document.getElementById('ball');
  var scoreT = document.getElementById('score'), overlay = document.getElementById('overlay');
  var score1 = 0, score2 = 0, py = 120, cy = 120, ballx = 170, bally = 150, vx = 3, vy = 2;
  var running = false, over = false, keys = {}, started = false;

  // —— retention + contact (shared pattern) ——
  var GAME = 'pong';
  var DAILY_GAMES = ['snake', '2048', 'pong', 'abtest', 'funnel', 'cohort', 'sql', 'metric', 'retention', 'bottleneck'];
  var LS_BEST = 'arcade_best_' + GAME;
  var cta = document.getElementById('cta');
  var IS_LOCAL = /^(localhost|127\.0\.0\.1|::1|0\.0\.0\.0)$/.test(window.location.hostname);
  var PH_KEY = 'phc_tdju2w288PnkFE2e96efWKpoCvBPHPtveSztZK9NnGrv';
  if (!IS_LOCAL && PH_KEY.indexOf('__PH_') !== 0 && !window.posthog) {
    try {
      var phs = document.createElementNS('http://www.w3.org/2000/svg', 'script');
      phs.setAttribute('href', 'https://us-assets.i.posthog.com/static/array.js');
      phs.setAttribute('type', 'text/javascript');
      phs.onload = function () { try { window.posthog.init(PH_KEY, { defaults: '2026-05-30', persistence: 'localStorage+cookie', api_host: 'https://us.i.posthog.com', capture_pageview: true, capture_pageleave: true, autocapture: true, capture_exceptions: true, session_recording: { maskAllInputs: true } }); } catch (e) {} };
      document.documentElement.appendChild(phs);
    } catch (e) {}
  }
  function ph(name, props) { try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {} }
  function lsGet(k, d) { try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function winsOf() { return parseInt(lsGet(LS_BEST, '0'), 10) || 0; }
  function todayStr() { var n = new Date(); return n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  function todayGame() { return DAILY_GAMES[Math.floor(Date.now() / 86400000) % DAILY_GAMES.length]; }
  function markDaily() {
    var t = todayStr();
    var y = new Date(); y.setDate(y.getDate() - 1);
    var yst = y.getFullYear() + '-' + ('0' + (y.getMonth() + 1)).slice(-2) + '-' + ('0' + y.getDate()).slice(-2);
    var streak = lsGet('arcade_daily_date', '') === yst ? (parseInt(lsGet('arcade_streak', '0'), 10) || 0) + 1 : 1;
    lsSet('arcade_daily_date', t); lsSet('arcade_daily_done', '1'); lsSet('arcade_streak', String(streak));
    ph('daily_completed', { game: GAME, streak: streak });
  }
  function showCTA(on) { if (cta) cta.style.display = on ? 'block' : 'none'; }
  function wireCTA() {
    if (!cta) return;
    var links = cta.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function () {
        var href = this.getAttribute('href') || '';
        var channel = href.indexOf('linkedin') !== -1 ? 'linkedin' : (href.indexOf('t.me') !== -1 ? 'telegram' : 'other');
        ph('contact_click', { location: 'game_over', channel: channel, game: GAME });
      });
    }
  }
  // —— /retention ——

  function resetBall(dir) { ballx = 170; bally = 150; vx = 3 * dir; vy = (Math.random() < 0.5 ? -1 : 1) * 2; }

  function serve() {
    running = true; overlay.textContent = '';
    if (!started) { started = true; ph('game_started', { game: GAME }); }
    resetBall(Math.random() < 0.5 ? 1 : -1);
  }

  function draw() {
    p1.setAttribute('y', py);
    p2.setAttribute('y', cy);
    ball.setAttribute('cx', ballx);
    ball.setAttribute('cy', bally);
  }

  function step() {
    if (keys['ArrowUp'] || keys['w'] || keys['W']) py -= 6;
    if (keys['ArrowDown'] || keys['s'] || keys['S']) py += 6;
    py = Math.max(0, Math.min(H - 60, py));
    if (!running) { draw(); return; }
    // CPU: chases only when the ball comes its way, with positioning error.
    if (vx > 0) {
      var err = 10 + Math.random() * 40; // ±(10..50) px — sometimes misses
      var target = bally + (Math.random() < 0.5 ? -err : err);
      var center = cy + 30;
      if (center < target - 3) cy += 3.2;
      else if (center > target + 3) cy -= 3.2;
    } else if (cy > 110) { cy -= 1.6; } else if (cy < 130) { cy += 1.6; } // ease to center while ball is away
    cy = Math.max(0, Math.min(H - 60, cy));
    ballx += vx; bally += vy;
    if (bally <= 4) { bally = 4; vy = -vy; }
    if (bally >= H - 4) { bally = H - 4; vy = -vy; }
    if (vx < 0 && ballx <= 26 && ballx >= 8 && bally > py - 6 && bally < py + 66) { vx = Math.min(7, -vx * 1.05); ballx = 26; }
    if (vx > 0 && ballx >= 314 && ballx <= 332 && bally > cy - 6 && bally < cy + 66) { vx = Math.min(7, -vx * 1.05); ballx = 314; }
    if (ballx < -12) { score2++; resetBall(1); }
    if (ballx > W + 12) { score1++; resetBall(-1); }
    if (score1 >= 11 || score2 >= 11) {
      running = false; over = true;
      var win = score1 >= 11;
      if (win) {
        var w = winsOf() + 1;
        lsSet(LS_BEST, String(w));
        ph('best_broken', { game: GAME, old_best: w - 1, new_best: w, score: w });
        var isDaily = todayGame() === GAME;
        if (isDaily) markDaily();
        showCTA(true);
        ph('game_win', { game: GAME, wins: w, score1: score1, score2: score2, daily_done: !!isDaily });
      } else {
        showCTA(false);
        ph('game_over', { game: GAME, wins: winsOf(), score1: score1, score2: score2 });
      }
      overlay.textContent = (win ? 'YOU WIN! ' + winsOf() + ' wins' : 'CPU WINS') + ' · tap to restart';
      overlay.setAttribute('fill', win ? '#4ade80' : '#ff4b4b');
    }
    scoreT.textContent = score1 + ' : ' + score2 + ' · Wins: ' + winsOf();
    draw();
  }

  document.addEventListener('keydown', function (e) {
    keys[e.key] = true;
    if (e.key === 'r' || e.key === 'R') { score1 = 0; score2 = 0; py = 120; cy = 120; over = false; started = false; showCTA(false); scoreT.textContent = '0 : 0 · Wins: ' + winsOf(); serve(); return; }
    if (!running && !over) serve();
  });
  document.addEventListener('keyup', function (e) { keys[e.key] = false; });
  document.addEventListener('mousemove', function (e) {
    var rect = document.documentElement.getBoundingClientRect();
    var scale = H / rect.height;
    py = (e.clientY - rect.top) * scale - 80 - 30;
    py = Math.max(0, Math.min(H - 60, py));
  });

  // --- Touch controls (mobile) ---
  function touchPaddle(clientY) {
    var rect = document.documentElement.getBoundingClientRect();
    var scale = H / rect.height;
    py = (clientY - rect.top) * scale - 80 - 30;
    py = Math.max(0, Math.min(H - 60, py));
  }
  document.addEventListener('touchstart', function (e) {
    e.preventDefault();
    if (over) { score1 = 0; score2 = 0; py = 120; cy = 120; over = false; started = true; showCTA(false); scoreT.textContent = '0 : 0 · Wins: ' + winsOf(); serve(); return; }
    touchPaddle(e.touches[0].clientY);
    if (!running && !over) serve();
  }, {passive: false});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); touchPaddle(e.touches[0].clientY); }, {passive: false});

  wireCTA();
  setInterval(step, 16);
  draw();
  scoreT.textContent = '0 : 0 · Wins: ' + winsOf();
})();
